"""Email outbox for simulated retention communications."""

import pandas as pd
import streamlit as st

from customer_retention_automation.dashboard.api_client import ROUND_IDS

ACTION_LABELS = {
    "send_email": "Customer outreach",
    "offer_discount": "Discount offer",
}


def render_emails(email_jobs: list[dict]) -> None:
    """Render simulated retention emails and their details."""
    st.subheader("Email Outbox")
    st.caption(
        "Emails generated by the retention workflows. "
        "All deliveries are simulated; no real emails are sent."
    )

    search_col, round_col = st.columns([2, 1])

    with search_col:
        search = st.text_input(
            "Customer ID",
            placeholder="Search email jobs...",
            key="emails_customer_search",
        )

    with round_col:
        selected_round = st.selectbox(
            "Simulation round",
            ["All rounds", *ROUND_IDS],
            key="emails_round",
        )

    type_col, status_col = st.columns(2)

    with type_col:
        selected_type = st.selectbox(
            "Email type",
            [
                "All types",
                "Customer outreach",
                "Discount offer",
            ],
            key="emails_type",
        )

    with status_col:
        selected_status = st.selectbox(
            "Delivery status",
            ["All statuses", "Simulated", "Pending", "Failed"],
            key="emails_status",
        )

    visible_jobs = [
        job
        for job in email_jobs
        if search.lower() in job["customer_id"].lower()
        and (selected_round == "All rounds" or job["round_id"] == selected_round)
        and (
            selected_type == "All types"
            or ACTION_LABELS.get(job["action"]) == selected_type
        )
        and (
            selected_status == "All statuses"
            or job["status"] == selected_status.lower()
        )
    ]

    simulated = sum(job["status"] == "simulated" for job in visible_jobs)
    pending = sum(job["status"] == "pending" for job in visible_jobs)
    failed = sum(job["status"] == "failed" for job in visible_jobs)

    col1, col2, col3, col4 = st.columns(4)

    with col1:
        st.metric("Email jobs", len(visible_jobs))

    with col2:
        st.metric("Simulated", simulated)

    with col3:
        st.metric("Pending", pending)

    with col4:
        st.metric("Failed", failed)

    st.caption(f"Showing {len(visible_jobs)} of {len(email_jobs)} email jobs")

    if not visible_jobs:
        st.info("No email jobs match the selected filters.")
        return

    rows = [
        {
            "Round": job["round_id"],
            "Customer": job["customer_id"],
            "Type": ACTION_LABELS.get(job["action"], job["action"]),
            "Subject": job["subject"],
            "Status": job["status"].capitalize(),
            "Created": job.get("created_at"),
            "Simulated at": job.get("simulated_at"),
        }
        for job in visible_jobs
    ]

    frame = pd.DataFrame(rows).sort_values(
        ["Round", "Customer"],
        kind="stable",
    )

    st.dataframe(
        frame,
        hide_index=True,
        width="stretch",
        column_config={
            column: st.column_config.TextColumn(
                column,
                alignment="left",
            )
            for column in frame.columns
        },
    )

    st.download_button(
        "Export filtered email jobs as CSV",
        data=frame.to_csv(index=False).encode("utf-8"),
        file_name="retention_email_jobs.csv",
        mime="text/csv",
        key="emails_download",
    )

    st.divider()
    st.markdown("#### Email details")

    options = sorted(
        visible_jobs,
        key=lambda job: (
            job["round_id"],
            job["customer_id"],
        ),
    )

    selected_case_id = st.selectbox(
        "Select email",
        options=[job["case_id"] for job in options],
        format_func=lambda case_id: case_id,
        key="emails_selected_case",
    )

    selected_job = next(job for job in options if job["case_id"] == selected_case_id)

    with st.container(border=True):
        st.markdown(f"**{ACTION_LABELS.get(selected_job['action'], 'Email')}**")
        st.caption(
            f"{selected_job['round_id']} · "
            f"{selected_job['customer_id']} · "
            f"{selected_job['status'].capitalize()}"
        )

        st.markdown("**Subject**")
        st.write(selected_job["subject"])

        st.markdown("**Message**")
        st.text(selected_job["body"])

        st.caption(
            f"Created: {selected_job.get('created_at', '—')} "
            f"· Simulated: {selected_job.get('simulated_at') or '—'}"
        )

    st.caption("These are fictional messages. No customer was contacted.")
